import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static boolean isws(char c) {
        return c == ' ' || c == '\t' || c == 0x0B || c == '\f' || c == '\r';
    }

    static long joinedLen(List<String> v) {
        long n = 0;
        for (int i = 0; i < v.size(); i++) n += v.get(i).length() + (i > 0 ? 3 : 0);
        return n;
    }

    public static void main(String[] args) throws IOException {
        String raw = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        // Split into lines like str.splitlines() for \n and \r\n input.
        List<String> z = new ArrayList<>();
        int st = 0;
        while (st < raw.length()) {
            int e = raw.indexOf('\n', st);
            if (e < 0) e = raw.length();
            String line = raw.substring(st, e);
            if (line.endsWith("\r")) line = line.substring(0, line.length() - 1);
            z.add(line);
            st = e + 1;
        }
        long limit = Long.parseLong(z.get(0).trim());
        List<String> heads = new ArrayList<>(), cur = new ArrayList<>();
        StringBuilder out = new StringBuilder();
        boolean any = false;
        long curLen = 0; // length of " | ".join(cur)
        for (int li = 1; li < z.size(); li++) {
            String line = z.get(li);
            int k = 0;
            while (k < line.length() && isws(line.charAt(k))) k++;
            boolean ishead = k < line.length() && line.charAt(k) == '#';
            if (ishead) {
                int level = 0;
                while (k + level < line.length() && line.charAt(k + level) == '#') level++;
                while (heads.size() > level - 1) heads.remove(heads.size() - 1);
                heads.add(line);
            }
            long trial = curLen + line.length() + (cur.isEmpty() ? 0 : 3);
            if (!cur.isEmpty() && trial > limit) {
                if (any) out.append('\n');
                out.append(String.join(" | ", cur));
                any = true;
                cur = new ArrayList<>(heads);
                if (!ishead) cur.add(line);
                curLen = joinedLen(cur);
            } else {
                cur.add(line);
                curLen = trial;
            }
        }
        if (!cur.isEmpty()) {
            if (any) out.append('\n');
            out.append(String.join(" | ", cur));
        }
        out.append('\n');
        System.out.write(out.toString().getBytes(StandardCharsets.UTF_8));
        System.out.flush();
    }
}

package main

import (
	"io"
	"os"
	"strconv"
	"strings"
)

func isws(c byte) bool { return c == ' ' || c == '\t' || c == '\v' || c == '\f' || c == '\r' }

func joinedLen(v []string) int {
	n := 0
	for i, s := range v {
		n += len(s)
		if i > 0 {
			n += 3
		}
	}
	return n
}

func main() {
	b, _ := io.ReadAll(os.Stdin)
	raw := string(b)
	// Split into lines like str.splitlines() for \n and \r\n input.
	var z []string
	for st := 0; st < len(raw); {
		e := strings.IndexByte(raw[st:], '\n')
		if e < 0 {
			e = len(raw)
		} else {
			e += st
		}
		z = append(z, strings.TrimSuffix(raw[st:e], "\r"))
		st = e + 1
	}
	limit, _ := strconv.Atoi(strings.TrimSpace(z[0]))
	var heads, cur, chunks []string
	curLen := 0 // length of " | ".join(cur)
	for _, line := range z[1:] {
		k := 0
		for k < len(line) && isws(line[k]) {
			k++
		}
		ishead := k < len(line) && line[k] == '#'
		if ishead {
			level := 0
			for k+level < len(line) && line[k+level] == '#' {
				level++
			}
			if len(heads) > level-1 {
				heads = heads[:level-1]
			}
			heads = append(heads, line)
		}
		trial := curLen + len(line)
		if len(cur) > 0 {
			trial += 3
		}
		if len(cur) > 0 && trial > limit {
			chunks = append(chunks, strings.Join(cur, " | "))
			cur = append([]string{}, heads...)
			if !ishead {
				cur = append(cur, line)
			}
			curLen = joinedLen(cur)
		} else {
			cur = append(cur, line)
			curLen = trial
		}
	}
	if len(cur) > 0 {
		chunks = append(chunks, strings.Join(cur, " | "))
	}
	os.Stdout.WriteString(strings.Join(chunks, "\n") + "\n")
}
